            border-bottom: #77aaff 3px solid;
        }
        header a {
            color: #fff;
            text-decoration: none;
            text-transform: uppercase;
            font-size: 16px;
        }
        header ul {
            padding: 0;
            list-style: none;
        }
        header li {
            float: left;
            display: inline;
            padding: 0 20px 0 20px;
        }
        .featured-image {
            width: 100%;
            height: auto;
        }
        .post-title {
            font-size: 24px;
            margin: 20px 0;
        }
        .author-byline {
            font-style: italic;
            margin-bottom: 20px;
        }
        .post-content {
            margin-bottom: 40px;
        }
        .post-content h2 {
            color: #333;
        }
        .post-content p {
            margin-bottom: 20px;
        }
